function useRoute() {
  const current = () => decodeURIComponent(window.location.hash.slice(1) || '/');
  const [route, setRoute] = useState(current);
  useEffect(() => {
    const update = () => {
      setRoute(current());
      window.scrollTo(0, 0);
    };
    window.addEventListener('hashchange', update);
    return () => window.removeEventListener('hashchange', update);
  }, []);
  useEffect(() => {
    const names: Record<string, string> = {
      '/': 'Home', '/projects': 'Projects', '/projects/memore': 'MEMO:RE',
      '/projects/game': 'Kotlin Game', '/activities': 'Activities',
      '/activities/kaist': 'AI 공모전',
      '/about': 'About me',
    };
    document.title = `${names[route] ?? 'Portfolio'} | 안지원`;
  }, [route]);
  return route;
}

function InternalLink({ to, children, className = '', ariaLabel }: { to: string; children: ReactNode; className?: string; ariaLabel?: string }) {
  return <a href={`#${to}`} className={className} aria-label={ariaLabel}>{children}</a>;
}

